usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Responses.InputTokens.Count(
		context.TODO(),
		openai.ResponseInputTokenCountParams{
			Model: param.NewOpt[string]("string"),
			Input: "string",
			PreviousResponseID: param.NewOpt[string]("string"),
			Tools: []openai.Tool{openai.FunctionTool{Type: "function", Name: "string", Parameters: map[string]any{"key": nil}, Strict: true, Description: "string", DeferLoading: true}},
			Text: openai.ResponseTextParam{Format: openai.ResponseFormatText{Type: "text"}, Verbosity: openai.VerbosityLow},
			Reasoning: openai.Reasoning{Effort: openai.ReasoningEffortNone, Summary: openai.ReasoningSummaryAuto, GenerateSummary: openai.ReasoningSummaryAuto},
			Truncation: openai.TruncationEnumAuto,
			Instructions: param.NewOpt[string]("string"),
			Conversation: "string",
			ToolChoice: openai.ToolChoiceOptionsNone,
			ParallelToolCalls: param.NewOpt[bool](true),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
